const readRequestBuffer = (req, maximum) => new Promise((resolve, reject) => {
  const chunks = []; let size = 0;
  req.on('data', chunk => { size += chunk.length; if (size > maximum) { reject(Object.assign(new Error('PDF exceeds the 15 MB attachment limit.'), { statusCode: 413 })); req.destroy(); } else chunks.push(chunk); });
  req.on('end', () => resolve(Buffer.concat(chunks))); req.on('error', reject);
});
const parseMultipartPdf = async req => {
  const contentType = String(req.headers['content-type'] || '');
  const boundary = contentType.match(/boundary=(?:"([^"]+)"|([^;]+))/)?.slice(1).find(Boolean);
  if (!boundary) throw Object.assign(new Error('A multipart PDF upload is required.'), { statusCode: 400 });
  const raw = await readRequestBuffer(req, 15 * 1024 * 1024 + 1024 * 1024), marker = Buffer.from(`--${boundary}`);
  for (const part of raw.toString('latin1').split(marker.toString('latin1'))) {
    if (!/name="file"/i.test(part)) continue;
    const split = part.indexOf('\r\n\r\n'); if (split < 0) continue;
    const headers = part.slice(0, split), fileName = safeAttachmentName(headers.match(/filename="([^"]*)"/i)?.[1]);
    const mimeType = String(headers.match(/content-type:\s*([^\r\n]+)/i)?.[1] || '').toLowerCase();
    let content = Buffer.from(part.slice(split + 4), 'latin1'); if (content.subarray(-2).toString() === '\r\n') content = content.subarray(0, content.length - 2);
    if (!content.length || content.length > 15 * 1024 * 1024) throw Object.assign(new Error('PDF exceeds the 15 MB attachment limit.'), { statusCode: 413 });
    return validatePdfUpload({ fileName, mimeType, content });
  }
  throw Object.assign(new Error('Select a PDF file to upload.'), { statusCode: 400 });
};
