    if(!poLine) throw new Error(`Purchase Order line for ${line.inventoryId||line.poLineId||''} was not found.`);
    const qty=Number(line.qty||line.quantity||0); const item=itemMaster.find(i=>i.code===poLine.inventoryId); const basis=isStockItem(item)?Number(poLine.qtyReceived||0):Number(poLine.qtyOrdered||0); const available=Math.max(0,basis-Number(poLine.qtyBilled||0));
    if(qty>available) throw new Error(isStockItem(item)?'Cannot bill more than received quantity.':'Cannot bill more than ordered quantity.');
