    const receipt= line.receiptNumber ? purchaseReceipts.find(r=>r.receiptNumber===line.receiptNumber||r.id===line.receiptNumber) : null;
    if(receipt){ const rl=purchaseReceiptLines.find(x=>x.receiptId===receipt.id&&x.poLineId===poLine.id); if(rl) rl.qtyBilled=Number(rl.qtyBilled||0)+qty; }
